});

test('createInvoice applies silver tier discount (2.5%) when no discount specified', () => {
  const result = createInvoice({
    customerId: 'C-003', // Kite & Co, silver tier
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 2.5);
});

test('createInvoice applies standard tier discount (0%) when no discount specified', () => {
  const result = createInvoice({
    customerId: 'C-002', // Blue Fern Bakery, standard tier
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, undefined);
});

test('createInvoice explicit discount (0) overrides tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, undefined);
});

test('createInvoice explicit discount overrides tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 20 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 20);
});

test('createInvoice applies tier discount per customer for multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'ICON-SET', qty: 100 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5); // gold tier
  assert.equal(result.value.lines[1].discountPercent, 10); // explicit
  assert.equal(result.value.lines[2].discountPercent, 5); // gold tier
});

test('addLine adds a new line to an invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[1].sku, 'DES-HOUR');
  assert.equal(result.value.lines[1].qty, 3);
  assert.equal(result.value.lines[1].name, 'Design work (hour)');
  assert.equal(result.value.lines[1].unitPrice, 8500);
});

test('addLine increases qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].qty, 8);
  assert.equal(result.value.lines[0].name, 'Development (hour)');
});

test('addLine can add same SKU multiple times', () => {
  let invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  invoice = addLine(invoice, { sku: 'DEV-HOUR', qty: 2 }).value;
  invoice = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 }).value;

  assert.equal(invoice.lines[0].qty, 6);
});

test('addLine fails with NOT_DRAFT if status is not draft', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'sent',
    lines: [{ sku: 'DEV-HOUR', qty: 5, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 }],
  };

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 1 });

  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine fails with QTY_INVALID for bad quantities', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const cases = [0, -1, 1.5, NaN, null];

  for (const qty of cases) {
    const result = addLine(invoice, { sku: 'DES-HOUR', qty });
    assert.equal(result.ok, false, `Should fail for qty ${qty}`);
    assert.equal(result.error, 'QTY_INVALID', `Should fail with QTY_INVALID for qty ${qty}`);
  }
});

test('addLine fails with UNKNOWN_SKU for unknown product', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'FAKE-SKU', qty: 1 });

  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const originalLength = invoice.lines.length;

  addLine(invoice, { sku: 'DES-HOUR', qty: 3 });

  assert.equal(invoice.lines.length, originalLength);
  assert.equal(invoice.lines[0].qty, 5);
});

test('addLine accepts discountPercent', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3, discountPercent: 20 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 20);
});

test('addLine rejects invalid discountPercent', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 1, discountPercent: 150 });

  assert.deepEqual(result, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('addLine applies tier discount when adding new line without discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 5); // gold tier
});

test('addLine does not apply discount when qty is increased on existing line', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }], // explicit 10%
  }).value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 10); // unchanged
});

test('addLine explicit discount overrides tier discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3, discountPercent: 20 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 20); // explicit
});

test('invoiceTotals calculates discount correctly', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  const totals = invoiceTotals(result.value);

  // 10 × 9500 = 95000
  // 10% discount = 9500
  // After discount = 85500
  // 21% VAT on 85500 = 17955
  // total = 95000 - 9500 + 17955 = 103455
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.vat, 17955);
  assert.equal(totals.total, 103455);
});

test('invoiceTotals sums multiple line discounts', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 10, discountPercent: 20 },
    ],
  });

  const totals = invoiceTotals(result.value);

  // Line 1: 10 × 9500 = 95000, 10% = 9500, after discount = 85500, VAT 21% = 17955
  // Line 2: 10 × 8500 = 85000, 20% = 17000, after discount = 68000, VAT 21% = 14280
  // Subtotal = 180000, Discount = 26500, VAT = 32235, Total = 180000 - 26500 + 32235 = 185735
  assert.equal(totals.subtotal, 180000);
  assert.equal(totals.discount, 26500);
  assert.equal(totals.vat, 32235);
  assert.equal(totals.total, 185735);
});

test('invoiceTotals clamps total at zero', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', qty: 1, name: 'Development (hour)', unitPrice: 100, vatRate: 21, discountPercent: 150 },
    ],
  };

  const totals = invoiceTotals(invoice);

  // Even though discount would be more than subtotal, total is clamped at 0
  assert.equal(totals.subtotal, 100);
  assert.equal(totals.discount, 150);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with mixed discount and non-discount lines', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 }, // gets 0% (standard tier)
      { sku: 'DES-HOUR', qty: 5, discountPercent: 50 }, // explicit 50%
    ],
  });

  const totals = invoiceTotals(result.value);

  // Line 1: 5 × 9500 = 47500, 0% discount, VAT 21% = 9975
  // Line 2: 5 × 8500 = 42500, 50% = 21250 discount, after = 21250, VAT 21% = 4462.5 → 4462
  // Subtotal = 90000, Discount = 21250, VAT = 14437, Total = 90000 - 21250 + 14437 = 83187
  assert.equal(totals.subtotal, 90000);
  assert.equal(totals.discount, 21250);
  assert.equal(totals.vat, 14437);
  assert.equal(totals.total, 83187);
});

test('invoiceTotals includes VAT calculation', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(result.value);

  // 10 × 9500 = 95000 (subtotal)
  // No discount
  // 21% VAT on 95000 = 19950
  // Total = 95000 + 19950 = 114950
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 19950);
  assert.equal(totals.total, 114950);
});

test('invoiceTotals calculates VAT after discount', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier, 5%
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(result.value);

  // 10 × 9500 = 95000
  // 5% discount = 4750
  // After discount = 90250
  // 21% VAT on 90250 = 18952.5 → 18952 (banker's rounding: round half to even)
  // Total = 95000 - 4750 + 18952 = 109202
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 18952);
  assert.equal(totals.total, 109202);
});

test('invoiceTotals sums VAT from multiple lines with different rates', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 }, // 21% VAT
      { sku: 'PRINT-A4', qty: 500 }, // 9% VAT
    ],
  });

  const totals = invoiceTotals(result.value);

  // Line 1: 10 × 9500 = 95000, 21% VAT = 19950
  // Line 2: 500 × 37 = 18500, 9% VAT = 1665
  // Subtotal = 113500, VAT = 21615, Total = 135115
  assert.equal(totals.subtotal, 113500);
  assert.equal(totals.vat, 21615);
  assert.equal(totals.total, 135115);
});

test('invoiceTotals with 0% VAT line', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 }, // 21% VAT
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT (exempt)
    ],
  });

  const totals = invoiceTotals(result.value);

  // Line 1: 10 × 9500 = 95000, 21% VAT = 19950
  // Line 2: 1 × 60000 = 60000, 0% VAT = 0
  // Subtotal = 155000, VAT = 19950, Total = 174950
  assert.equal(totals.subtotal, 155000);
  assert.equal(totals.vat, 19950);
  assert.equal(totals.total, 174950);
});

